import java.util.Arrays;

public final class HeapSortTest {
    private HeapSortTest() {
    }

    public static void main(String[] args) {
        sortsEmptyArray();
        sortsSingleValue();
        sortsTwoValues();
        sortsDuplicateValues();
        sortsNegativeValues();
        sortsAlreadySortedValues();
        sortsReverseSortedValues();
        supportsOriginalMethodName();
        rejectsNullInput();
    }

    private static void sortsEmptyArray() {
        assertSorted(new int[] {});
    }

    private static void sortsSingleValue() {
        assertSorted(new int[] {1});
    }

    private static void sortsTwoValues() {
        assertSorted(new int[] {2, 1});
    }

    private static void sortsDuplicateValues() {
        assertSorted(new int[] {3, 3, 1, 2, 3});
    }

    private static void sortsNegativeValues() {
        assertSorted(new int[] {-5, 0, -2, 7, 7});
    }

    private static void sortsAlreadySortedValues() {
        assertSorted(new int[] {1, 2, 3, 4, 5});
    }

    private static void sortsReverseSortedValues() {
        assertSorted(new int[] {5, 4, 3, 2, 1});
    }

    private static void supportsOriginalMethodName() {
        int[] values = {4, 2, 1, 3};
        int[] expected = sortedCopy(values);

        HeapSort.heapSort(values);

        assertArrayEquals(expected, values);
    }

    private static void rejectsNullInput() {
        assertThrowsNullPointer(() -> HeapSort.sort(null));
        assertThrowsNullPointer(() -> HeapSort.heapSort(null));
    }

    private static void assertSorted(int[] values) {
        int[] expected = sortedCopy(values);

        HeapSort.sort(values);

        assertArrayEquals(expected, values);
    }

    private static int[] sortedCopy(int[] values) {
        int[] expected = Arrays.copyOf(values, values.length);
        Arrays.sort(expected);
        return expected;
    }

    private static void assertArrayEquals(int[] expected, int[] actual) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(
                    "Expected " + Arrays.toString(expected) + " but got " + Arrays.toString(actual));
        }
    }

    private static void assertThrowsNullPointer(Runnable action) {
        try {
            action.run();
        } catch (NullPointerException expected) {
            return;
        }

        throw new AssertionError("Expected NullPointerException");
    }
}

import java.util.Objects;

/**
 * In-place heap sort for integer arrays.
 */
public final class HeapSort {
    private HeapSort() {
    }

    /**
     * Sorts {@code values} in ascending order.
     *
     * @param values the array to sort
     * @throws NullPointerException if {@code values} is null
     */
    public static void sort(int[] values) {
        Objects.requireNonNull(values, "values");

        if (values.length < 2) {
            return;
        }

        MaxHeap.from(values).sortAscending();
    }

    /**
     * Compatibility wrapper for callers that use the original method name.
     *
     * @param values the array to sort
     * @throws NullPointerException if {@code values} is null
     */
    public static void heapSort(int[] values) {
        sort(values);
    }

    private static final class MaxHeap {
        private static final int ROOT_INDEX = 0;

        private final int[] values;
        private int size;

        private MaxHeap(int[] values) {
            this.values = values;
            size = values.length;
        }

        private static MaxHeap from(int[] values) {
            MaxHeap heap = new MaxHeap(values);
            heap.build();
            return heap;
        }

        private void sortAscending() {
            while (size > 1) {
                moveMaxToEnd();
                siftDown(ROOT_INDEX);
            }
        }

        private void build() {
            for (int index = firstParentIndex(); index >= 0; index--) {
                siftDown(index);
            }
        }

        private int firstParentIndex() {
            return size / 2 - 1;
        }

        private void moveMaxToEnd() {
            size--;
            swap(ROOT_INDEX, size);
        }

        private void siftDown(int rootIndex) {
            int currentIndex = rootIndex;

            while (true) {
                int largestIndex = largestIndexInSubtree(currentIndex);

                if (largestIndex == currentIndex) {
                    return;
                }

                swap(currentIndex, largestIndex);
                currentIndex = largestIndex;
            }
        }

        private int largestIndexInSubtree(int rootIndex) {
            int largestIndex = rootIndex;
            int leftChildIndex = leftChildIndex(rootIndex);
            int rightChildIndex = rightChildIndex(rootIndex);

            if (isGreater(leftChildIndex, largestIndex)) {
                largestIndex = leftChildIndex;
            }

            if (isGreater(rightChildIndex, largestIndex)) {
                largestIndex = rightChildIndex;
            }

            return largestIndex;
        }

        private boolean isGreater(int candidateIndex, int currentIndex) {
            return candidateIndex < size && values[candidateIndex] > values[currentIndex];
        }

        private static int leftChildIndex(int index) {
            return 2 * index + 1;
        }

        private static int rightChildIndex(int index) {
            return 2 * index + 2;
        }

        private void swap(int firstIndex, int secondIndex) {
            int value = values[firstIndex];
            values[firstIndex] = values[secondIndex];
            values[secondIndex] = value;
        }
    }

    public static void main(String[] args) {
        HeapSortDemo.main(args);
    }
}

